declare(strict_types=1);require_once __DIR__.'/../../config/database.php';header('Content-Type: application/json; charset=utf-8');$auth=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer\s+(.+)$/',$auth,$m)){http_response_code(401);echo json_encode(['error'=>'API anahtarı gerekli']);exit;}$hash=hash('sha256',$m[1]);$q=db()->prepare("SELECT k.* FROM agency_api_keys k JOIN agencies a ON a.id=k.agency_id WHERE k.key_hash=? AND k.status='active' AND a.status='active' LIMIT 1");$q->execute([$hash]);$key=$q->fetch();if(!$key){http_response_code(401);echo json_encode(['error'=>'Geçersiz API anahtarı']);exit;}db()->prepare('UPDATE agency_api_keys SET last_used_at=now() WHERE id=?')->execute([$key['id']]);$rows=db()->query("SELECT id,property_type,name,city,country_code,product_details FROM properties WHERE status='active' ORDER BY id DESC LIMIT 100")->fetchAll();echo json_encode(['data'=>$rows,'meta'=>['count'=>count($rows)]],JSON_UNESCAPED_UNICODE);
